const signals=[
{name:['AI Crawler Access','Quyền truy cập của bot AI'],value:14,max:20,desc:['Whether relevant AI crawlers can read your website','Các bot AI phù hợp có thể đọc website hay không'],finding:['Some AI crawlers cannot access key content pages','Một số bot AI chưa được truy cập các trang nội dung chính'],fix:['Review robots.txt permissions for each relevant crawler','Rà soát robots.txt theo từng bot AI phù hợp']},
{name:['llms.txt','llms.txt'],value:0,max:10,desc:['An optional file describing key content and services','Tệp tham khảo mô tả nội dung và dịch vụ chính'],finding:['No llms.txt file is present in this example','Ví dụ này chưa có tệp llms.txt'],fix:['Consider adding llms.txt after reviewing the content structure','Cân nhắc bổ sung llms.txt sau khi rà soát cấu trúc nội dung']},
{name:['Structured Data','Dữ liệu có cấu trúc'],value:12,max:20,desc:['How your business and page content are described in schema','Cách schema mô tả doanh nghiệp và nội dung trang'],finding:['Organization details and identity links are incomplete','Thông tin tổ chức và liên kết xác thực chưa đầy đủ'],fix:['Complete Organization, sameAs and relevant page-level schema','Hoàn thiện Organization, sameAs và schema phù hợp từng trang']},
{name:['Content Extractability','Khả năng trích xuất nội dung'],value:16,max:20,desc:['How clearly key questions are answered in readable content','Mức rõ ràng của câu trả lời trong nội dung có thể đọc'],finding:['Some answers are difficult to locate within the content','Một số câu trả lời còn khó tìm trong nội dung'],fix:['Place direct answers under headings based on customer questions','Đặt câu trả lời trực tiếp dưới tiêu đề gắn với câu hỏi của khách hàng']},
{name:['E-E-A-T','E-E-A-T'],value:9,max:15,desc:['Authorship, references and evidence behind your content','Tác giả, nguồn tham khảo và căn cứ cho nội dung'],finding:['Authorship details and references are inconsistent','Thông tin tác giả và nguồn tham khảo chưa nhất quán'],fix:['Identify the content owner and cite sources for factual claims','Nêu người chịu trách nhiệm nội dung và nguồn cho các nhận định']},
{name:['Technical','Kỹ thuật'],value:11,max:15,desc:['Foundations such as metadata, canonical and mobile access','Nền tảng như metadata, canonical và khả năng truy cập trên mobile'],finding:['Some pages need canonical and mobile checks','Một số trang cần kiểm tra canonical và trải nghiệm mobile'],fix:['Review indexing settings and content accessibility on mobile','Rà soát cấu hình lập chỉ mục và khả năng đọc nội dung trên mobile']}];
const initialBooking=()=>({name:'',company:'',country:'',language:'vi',slot:''});
const state={lang:'vi',input:{site:'',email:'',privacy:false,newsletter:false},error:'',invalid:'',info:'',busy:false,failure:'',current:null,leads:[],modal:null,modalLead:null,booking:initialBooking(),bookingError:'',bookingInvalid:'',scenario:'success',counter:0,generation:0};
const slots=['2026-10-23T10:00:00+07:00','2026-10-23T14:00:00+07:00','2026-10-26T10:00:00+07:00'];
let activeRoute='',originControl=null;
const t=k=>copy[k]?.[state.lang==='en'?0:1]||k;
const tr=a=>a[state.lang==='en'?0:1];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=(v,a)=>v?' '+a:'';
const fmt=(date,short=false)=>new Intl.DateTimeFormat(state.lang==='en'?'en-GB':'vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'short',...(short?{}:{hour:'2-digit',minute:'2-digit',hour12:false})}).format(new Date(date));
const route=()=>location.hash==='#workspace'?'workspace':location.hash==='#inbox'?'inbox':'main';
const arrow='<span aria-hidden="true">↗</span>';
/* Shared AI Visibility criteria with SEO benefit annotations */
const signalGroups=[{id:'ai',name:['AI Visibility','AI Visibility'],indices:[0,3,2,4,5,1]}];
const groupedSignalIndexes=signalGroups[0].indices;
const seoSharedSignals=new Set([2,3,4,5]);
function seoLabel(i){return seoSharedSignals.has(i)?`<span class="seo-support">${tr(['Also supports SEO','Hỗ trợ cả SEO'])}</span>`:''}
const groupScore=g=>({value:g.indices.reduce((n,i)=>n+signals[i].value,0),max:g.indices.reduce((n,i)=>n+signals[i].max,0)});
function signalGroupsLanding(){return `<section class="section" id="checks"><div class="eyebrow">${t('sixLabel')}</div><h2>${t('sixTitle')}</h2><p class="lead">${t('sixBody')}</p><div class="ai-signal-grid">${groupedSignalIndexes.map(i=>{const p=signals[i];return `<details class="ai-signal-card"${attr(!matchMedia('(max-width:599px)').matches,'open')}><summary><span class="signal-card-title">${tr(p.name)}${seoLabel(i)}</span><small>/ ${p.max}</small></summary><p>${tr(p.desc)}</p></details>`}).join('')}</div></section>`}
function groupedSignalRows(){return `<div class="preview-group">${groupedSignalIndexes.map(i=>{const p=signals[i];return `<div class="preview-row"><span>${tr(p.name)}${seoLabel(i)}</span><b>${p.value} / ${p.max}</b></div>`}).join('')}</div>`}
function groupScoreSummary(){return `<div class="group-score-summary unified-score"><div class="overall-readiness"><span>${tr(['AI Visibility readiness','Mức sẵn sàng AI Visibility'])}</span><strong>${signals.reduce((n,s)=>n+s.value,0)}<small> / 100</small></strong></div><p class="small">${tr(['Six website signals, one readiness score','Sáu tín hiệu website, một điểm đánh giá'])}</p></div>`}
function groupedTechnicalPanel(){return `<div class="strategy-head"><h3>${tr(['AI Visibility checks','Các kiểm tra AI Visibility'])}</h3></div><div class="cms-context">${contextSelect('report-cms',rt('cms'),[['wordpress','WordPress'],['shopify','Shopify'],['other',tr(['Other / custom','Khác / tùy chỉnh'])]],reportUI.cms)}<p class="fine">${rt('cmsNote')}</p></div><div class="technical-groups">${groupedSignalIndexes.map(i=>technicalSignal(signals[i],i)).join('')}</div>`}
function groupedEmailContent(l){return `<h2 id="dialog-title">${t('emailTitle')}</h2><p class="small">${t('to')}: ${esc(l.email)}<br>${t('subject')}: ${t('emailSubject')}</p><div class="email-paper"><div class="eyebrow">DSQUARE</div><h3 style="margin-top:15px">${esc(l.site)}</h3><p class="small">${tr(['Your AI Visibility readiness across six website signals','Mức sẵn sàng AI Visibility qua sáu tín hiệu website'])}</p><div class="email-score">${signals.reduce((n,s)=>n+s.value,0)} <small>/ 100</small></div>${groupedSignalRows()}<p class="email-group-action"><b>${tr(['Next step','Bước tiếp theo'])}</b><br>${tr(signals[0].fix)}</p><button class="primary wide" type="button" data-action="book" data-id="${l.id}">${rt('talk')}${arrow}</button></div><p class="fine" style="margin:15px 0 0">${t('emailFoot')}</p>`}

