 [['Page titles','Tiêu đề trang'],3,3], [['Meta descriptions','Meta description'],3,3], [['Canonical URLs','URL canonical'],0,3], [['Mobile readability','Nội dung đọc được trên mobile'],3,3], [['Sitemap coverage','Độ bao phủ sitemap'],2,3]
